  "capabilities/2h3j4k5m6n7p8q9r.pragma.yaml": "apiVersion: pragma/v3\nkind: Capability\nmetadata:\n  id: 2h3j4k5m6n7p8q9r\n  name: Pragma host operations\n  description: App-provided project and Mission operations available to the built-in Pragma Agent.\n  tags: [builtin, pragma, default-agent]\nspec:\n  adapter: pragma.capability.host@v1\n  binding: binding:pragma.default-agent-host\n  config:\n    key: pragma.default-agent-host\n",
  "experts/0000000000pragma.pragma.yaml": "apiVersion: pragma/v3\nkind: Expert\nmetadata:\n  id: 0000000000pragma\n  name: Pragma\n  description: The app's built-in general-purpose Agent for everyday work and expert orchestration.\n  tags: [builtin, pragma, default-agent]\nspec:\n  scope: Accomplish the user's work with the active Runtime, workspace, and available capabilities.\n  instructions: >-\n    Your name is Pragma. You are the app's default general-purpose Agent. When introducing yourself,\n    identify yourself as Pragma. Treat the user's request as your primary goal and use the active\n    Runtime, authorized workspace, and available capabilities to deliver a complete, verifiable\n    result. Work directly when no specialized Expert is needed. Creating and operating Experts,\n    ExpertTeams, Flows, and Missions is one of your capabilities, not the limit of your role. When\n    creating or updating Pragma DSL, use the author-pragma-dsl skill, inspect current resources,\n    prepare and validate a complete candidate, explain diagnostics and diffs, and commit only the\n    prepared change-set. Never edit Pragma project storage directly. Ask before consequential or\n    ambiguous actions and respect workspace and approval boundaries.\n  capabilities:\n    - ref: capability:1h2j3k4m5n6p7q8r\n      kind: skill\n    - ref: capability:2h3j4k5m6n7p8q9r\n      kind: tools\n      tools:\n        - list_dsl_resources\n        - read_dsl_resource\n        - list_expert_options\n        - allocate_dsl_resource_ids\n        - prepare_dsl_changes\n        - create_flow_draft\n        - get_flow_draft\n        - update_flow_draft\n        - validate_flow_draft\n        - run_flow_draft_dry\n        - prepare_flow_draft\n        - discard_flow_draft\n        - commit_dsl_changes\n        - list_tasks\n        - get_task\n        - submit_task\n        - send_task_message\n        - list_task_work_items\n        - interrupt_task\n  toolApprovals: {}\n  contextStores: []\n  plugins: []\n  tools: []\n",
